const raw = $input.first().json.output;

let cleaned = raw.trim();

// Remove markdown code blocks if present
cleaned = cleaned.replace(/```json\n?/gi, '').replace(/```\n?/gi, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('The Decider did not return valid JSON. Raw output: ' + raw);
}

return [{ json: parsed }];

const d = $input.first().json;

const instructions = Array.isArray(d.key_instructions)
  ? d.key_instructions.map(i => `- ${i}`).join('\n')
  : '- Be specific and clear\n- Avoid filler content\n- Use examples where helpful';

const constraints = Array.isArray(d.constraints)
  ? d.constraints.map(c => `- ${c}`).join('\n')
  : '- Do not add unnecessary filler\n- Always stay on topic';

const prompt = `You are The Answerer — a world-class prompt engineer.

Using the plan below, write a complete, professional, and optimized AI prompt.

PLAN:
- Intent: ${d.intent || 'Not specified'}
- Role: ${d.role || 'Expert'}
- Audience: ${d.audience || 'General'}
- Tone: ${d.tone || 'Professional'}
- Format: ${d.format || 'Paragraphs'}
- Length: ${d.length || 'Medium'}
- Goal: ${d.goal || 'Deliver the best possible result'}

Now write the full professional prompt using this exact structure:

---
# ROLE
You are a ${d.role || '[expert]'}. You have deep expertise in this area.

# TASK
[Write a clear 1-3 sentence task based on: ${d.intent || 'the user intent'}]

# CONTEXT
- Audience: ${d.audience || 'General audience'}
- Purpose: ${d.intent || 'To accomplish the stated goal'}
- Background: [Infer relevant background from the intent]

# INSTRUCTIONS
${instructions}

# OUTPUT FORMAT
- Format: ${d.format || 'Paragraphs'}
- Length: ${d.length || 'Medium'}
- Tone: ${d.tone || 'Professional'}

# CONSTRAINTS
${constraints}

# GOAL
${d.goal || 'Deliver a clear, actionable, high-quality result.'}
---

Output only the final prompt. No extra commentary.`;

return [{ json: { prompt } }];
